def dicts_equal(dict1, dict2):
    """Compare two dictionaries accounting for potential ordering differences and tuple->list conversions."""
    if set(dict1.keys()) != set(dict2.keys()):
        return False

    for key in dict1.keys():
        val1, val2 = dict1[key], dict2[key]
        # Handle tuple->list conversion
        if isinstance(val1, tuple) and isinstance(val2, list):
            if list(val1) != val2:
                return False
        elif isinstance(val1, dict) and isinstance(val2, dict):
            if not dicts_equal(val1, val2):
                return False
        elif val1 != val2:
            return False
    return True


